#!/usr/bin/env python3
"""Test suite for envparse.py"""

from envparse import parse_env


def test_basic():
    """Test basic key=value parsing"""
    assert parse_env("A=1\nB = 2 \n") == {"A": "1", "B": "2"}
    print("✓ test_basic")


def test_comments_and_whitespace():
    """Test skipping comments and whitespace"""
    assert parse_env("# c\n\n   \nA=1") == {"A": "1"}
    print("✓ test_comments_and_whitespace")


def test_double_quote_escapes():
    """Test double-quoted strings with escape sequences"""
    assert parse_env('A="x\\ny"') == {"A": "x\ny"}
    print("✓ test_double_quote_escapes")


def test_single_quote_literal():
    """Test single-quoted strings (literal, no escapes)"""
    assert parse_env("A='x\\ny'") == {"A": "x\\ny"}
    print("✓ test_single_quote_literal")


def test_trailing_comment():
    """Test unquoted value with trailing comment"""
    assert parse_env("A=hello  # trailing") == {"A": "hello"}
    print("✓ test_trailing_comment")


def test_hash_without_space():
    """Test hash not preceded by whitespace is part of value"""
    assert parse_env("A=a#b") == {"A": "a#b"}
    print("✓ test_hash_without_space")


def test_export_prefix():
    """Test export prefix removal"""
    assert parse_env("export FOO=bar") == {"FOO": "bar"}
    print("✓ test_export_prefix")


def test_duplicate_keys():
    """Test last occurrence wins"""
    assert parse_env("A=1\nA=2") == {"A": "2"}
    print("✓ test_duplicate_keys")


def test_empty_value():
    """Test empty value"""
    assert parse_env("A=") == {"A": ""}
    print("✓ test_empty_value")


def test_padded_quoted_value():
    """Test quoted values preserve internal whitespace"""
    assert parse_env('A="  padded  "') == {"A": "  padded  "}
    print("✓ test_padded_quoted_value")


def test_url_unquoted():
    """Test unquoted URL with multiple equals"""
    assert parse_env("URL=https://x/y?a=b") == {"URL": "https://x/y?a=b"}
    print("✓ test_url_unquoted")


def test_missing_equals():
    """Test error on missing equals"""
    try:
        parse_env("A=1\nnope\n")
        assert False, "Should raise ValueError"
    except ValueError as e:
        assert str(e) == "invalid line 2: nope"
    print("✓ test_missing_equals")


def test_invalid_key_starts_with_digit():
    """Test error on invalid key starting with digit"""
    try:
        parse_env("1BAD=x")
        assert False, "Should raise ValueError"
    except ValueError as e:
        assert str(e) == "invalid line 1: 1BAD=x"
    print("✓ test_invalid_key_starts_with_digit")


def test_empty_key():
    """Test error on empty key"""
    try:
        parse_env("=x")
        assert False, "Should raise ValueError"
    except ValueError as e:
        assert str(e) == "invalid line 1: =x"
    print("✓ test_empty_key")


def test_key_order_with_duplicates():
    """Test that order follows first appearance"""
    result = parse_env("A=1\nB=2\nA=3")
    keys = list(result.keys())
    assert keys == ["A", "B"], f"Expected ['A', 'B'], got {keys}"
    assert result == {"A": "3", "B": "2"}
    print("✓ test_key_order_with_duplicates")


def test_escape_sequences():
    """Test various escape sequences"""
    assert parse_env('A="\\n\\t\\r\\"\\\\test"') == {"A": "\n\t\r\"\\test"}
    print("✓ test_escape_sequences")


def test_unknown_escape_left_as_is():
    """Test unknown escape sequences are left as-is"""
    assert parse_env('A="\\x"') == {"A": "\\x"}
    print("✓ test_unknown_escape_left_as_is")


def test_carriage_return_stripped():
    """Test trailing \\r is stripped from lines"""
    assert parse_env("A=1\r\nB=2") == {"A": "1", "B": "2"}
    print("✓ test_carriage_return_stripped")


def test_export_with_spaces():
    """Test export with multiple spaces"""
    assert parse_env("export  FOO=bar") == {"FOO": "bar"}
    print("✓ test_export_with_spaces")


def test_comment_with_leading_spaces():
    """Test comment with leading spaces"""
    assert parse_env("   # comment\nA=1") == {"A": "1"}
    print("✓ test_comment_with_leading_spaces")


if __name__ == "__main__":
    test_basic()
    test_comments_and_whitespace()
    test_double_quote_escapes()
    test_single_quote_literal()
    test_trailing_comment()
    test_hash_without_space()
    test_export_prefix()
    test_duplicate_keys()
    test_empty_value()
    test_padded_quoted_value()
    test_url_unquoted()
    test_missing_equals()
    test_invalid_key_starts_with_digit()
    test_empty_key()
    test_key_order_with_duplicates()
    test_escape_sequences()
    test_unknown_escape_left_as_is()
    test_carriage_return_stripped()
    test_export_with_spaces()
    test_comment_with_leading_spaces()
    print("\n✅ All tests passed!")

